input.command:
cd /d/robot_cell; S="$LOCALAPPDATA/Temp/claude/43f48c4257a38110/600697e2-60a3-4d18-a896-189ef5a5ce1b/scratchpad"; S=$(cygpath -u "$S"); cat > "$S/probe.py" <<'EOF'
import cadquery as cq, sys, math
from collections import defaultdict
for name in ["3D_model/new_asm/bottom_cover.STEP","3D_model/new_asm/top_rod_onepiece.STEP"]:
    s = cq.importers.importStep(name).val()
    bb = s.BoundingBox()
    print("==",name); print(" bbox x %.1f..%.1f y %.1f..%.1f z %.1f..%.1f  vol %.0f mm3"%(bb.xmin,bb.xmax,bb.ymin,bb.ymax,bb.zmin,bb.zmax,s.Volume()))
    cyl = defaultdict(list)
    for f in s.Faces():
        if f.geomType()=="CYLINDER":
            from OCP.BRepAdaptor import BRepAdaptor_Surface
            a = BRepAdaptor_Surface(f.wrapped).Cylinder()
            ax=a.Axis(); p=ax.Location(); d=ax.Direction(); fb=f.BoundingBox()
            cyl[(round(a.Radius()*2,2),(round(abs(d.X()),1),round(abs(d.Y()),1),round(abs(d.Z()),1)))].append((round(p.X(),2),round(p.Y(),2),round(p.Z(),2),round(fb.xmin,1),round(fb.xmax,1),round(fb.ymin,1),round(fb.ymax,1),round(fb.zmin,1),round(fb.zmax,1)))
    for k in sorted(cyl):
        print(" D%.2f axis%s n=%d"%(k[0],k[1],len(cyl[k])))
        seen=set()
        for v in cyl[k]:
            key=v[:3]
            if key in seen: continue
            seen.add(key); print("    loc",v[:3],"bbox x",v[3:5],"y",v[5:7],"z",v[7:9])
    pl=defaultdict(float)
    for f in s.Faces():
        if f.geomType()=="PLANE":
            n=f.normalAt(); c=f.Center()
            for i,ax in enumerate("xyz"):
                if abs(abs([n.x,n.y,n.z][i])-1)<1e-6:
                    pl[(ax,round([c.x,c.y,c.z][i],2) if False else round([f.BoundingBox().xmin,f.BoundingBox().ymin,f.BoundingBox().zmin][i],2))]+=f.Area()
    for ax in "xyz":
        print(" planes ⟂",ax,[(k[1],round(v)) for k,v in sorted(pl.items()) if k[0]==ax and v>30])
EOF
/d/miniconda/envs/cad/python.exe "$(cygpath -w "$S/probe.py")" > "$S/probe.txt" 2>&1; wc -l "$S/probe.txt"; head -150 "$S/probe.txt"

