import json,sys
d=json.load(sys.stdin)
def walk(o):
    if isinstance(o,dict):
        if 'width_mm' in o and 'name' in o: yield o
        for v in o.values(): yield from walk(v)
    elif isinstance(o,list):
        for v in o: yield from walk(v)
sl=[s for s in walk(d) if s.get('width_mm')]
def n(W,w,g): return int((W+g)//(w+g))
