    for g in (8,10,12,14,15,16,18,20,22,25,26,28,30):
        lost=[n(s['width_mm'],w,8)-n(s['width_mm'],w,g) for s in sl]
        print('  间隙%2d: 少0列%2d个 少1列%2d个 少2列及以上%2d个' % (g, lost.count(0), lost.count(1), sum(1 for x in lost if x>=2)))
print([ (s['name'], s['width_mm'], n(s['width_mm'],60,8)) for s in sl])
"

