def pick(arm, suck, target, dry=False):
    sw = Stopwatch()
    act = "吸取"
    gx, gy = target["grasp_xy"]; face_z = target["face_z"]; grz = float(target["grasp_rz"])
    gz, hz, lz = face_z + PRESS_M, face_z + PRESS_M + HOVER_M, face_z + LIFT_M
    data = {"落点": "(%.3f, %.3f) 面高%.3f" % (gx, gy, face_z), "吸取z/悬停z/抬升z": "%.3f / %.3f / %.3f" % (gz, hz, lz),
