    cur = arm.get_tcp_pose_with_tool(tool=ARM_TOOL, wobj="")
    if cur is None:
        return ActionResult(act, False, "E_ARM_READ", C.FATAL, "读不到TCP", P.NONE, "不明", sw.s(), data)
    where0 = "TCP(%.2f,%.2f,%.2f)" % (cur.x, cur.y, cur.z)
    vertical = abs(abs(cur.rx) - math.pi) < 0.2 and abs(cur.ry) < 0.2
    # 2026-09-15 立放末端杆长 +66mm: 近拍位(相机45cm)时 TCP 已低于悬停高 → 入口改为"吸盘头高于盒顶 CLEAR_M", 低于悬停高则先竖直升到悬停高再平移
