    rows = [json.loads(l) for l in io.open(f, encoding="utf-8") if l.strip()]
    rows = rows[max(i for i, r in enumerate(rows) if r.get("seq") == 1):]
    k = {}
    for r in rows: k[r["kind"]] = k.get(r["kind"], 0) + 1
    print("== 任务", tid, rows[0]["t"], "->", rows[-1]["t"], "最后:", rows[-1]["kind"], rows[-1].get("state"), rows[-1].get("reason"), rows[-1].get("text", "")[:120])
