def play_path(cobot, path_file, v=0.25, a=0.25, start_tol=0.05, timeout=90.0, step=0.05, stall_s=2.5,
              prefix_pts=None, suffix_pts=None):
    """在cobot(已连接的DucoCobot裸客户端)上播放路径文件。
    返回(ok, rec); 起点偏差超限抛RuntimeError(不动)。rec=[[t,j1..j6],...]供存档。"""
    pts = [r[1:7] for r in json.load(open(path_file))["traj"]]
    # 接头并队(2026-09-02): 前缀=当前位置→路径起点的关节直线(与movej几何相同), 后缀=路径终点→下一位姿;
    # 全部进同一条track队列, 接头处只拐弯不停车
    if prefix_pts:
        pts = list(prefix_pts) + pts
    return play_points(cobot, pts, v=v, a=a, start_tol=start_tol, timeout=timeout, step=step, stall_s=stall_s, label=path_file,
                       raw_tail=list(suffix_pts) if suffix_pts else None)


def play_points(cobot, pts, v=0.25, a=0.25, start_tol=0.05, timeout=90.0, step=0.05, stall_s=2.5, label="points", raw_tail=None):
    """在已有连接上把一串关节路点(含起点)当一条track连续播完。play_path的内核; 丢回的两段movej并队也用它。
    raw_tail: 不参与重采样、原样追加在队列末尾的点(回程并队尾段稀疏化用: 稀疏→队列放慢过渡, 到点不急刹)"""
    target = (raw_tail or pts)[-1]
    cur = cobot.get_actual_joints_position()
    dev = max(abs(x - y) for x, y in zip(cur, pts[0]))
    if dev > start_tol:
        raise RuntimeError("起点偏差%.3frad>%.2f, 拒播 %s" % (dev, start_tol, label))
    # 重采样到间距≈step: 先抽稀(录制路径0.05密集, 点数=时长地板, 2026-09-01实证
    # 加密只加不减故仅调step无效; v1快=路点本来就稀), 再对大间隙插值兜底
    sparse = [pts[0]]
    for q in pts[1:-1]:
        if max(abs(x - y) for x, y in zip(q, sparse[-1])) >= step:
            sparse.append(q)
    sparse.append(pts[-1])
    dense = [sparse[0]]
    for a_, b_ in zip(sparse, sparse[1:]):
        steps = max(1, int(math.ceil(max(abs(x - y) for x, y in zip(a_, b_)) / max(step, 0.05))))
        for k in range(1, steps + 1):
            dense.append([x + (y - x) * k / steps for x, y in zip(a_, b_)])
    if raw_tail:
        dense = dense + list(raw_tail)
    print("    [track] 原始%d点 → 重采样%d点(间距%.2frad%s) v=%.2f" % (len(pts), len(dense), step, (", 尾段原样%d点" % len(raw_tail)) if raw_tail else "", v))
    try:                                     # 脚印(2026-10-23): 整串路点记下来, 复位时从当前点倒序播回出发点
        from actions import breadcrumb as _bc
        _bc.push("track", [float(x) for x in cur], pts=[[round(float(x), 5) for x in q] for q in dense], label=str(label)[-80:])
    except Exception:
        pass
    cobot.trackClearQueue()
    for i in range(0, len(dense), 50):
        cobot.trackEnqueue(dense[i:i + 50], True)
    cobot.trackJointMotion(v, a, False)
    rec, t0, settled = [], time.time(), 0
    last_j, last_move_t = None, time.time()
    while time.time() - t0 < timeout:
        j = cobot.get_actual_joints_position()
        if j and len(j) == 6:
            rec.append([round(time.time() - t0, 3)] + [float(x) for x in j])
            if max(abs(x - y) for x, y in zip(j, target)) < 0.002:
                settled += 1
                if settled >= 5:
                    return True, rec
            else:
                settled = 0
            # 停滞判定(2026-09-02): 急停/断线stop后臂不再动, 不必傻等到timeout
            if last_j is None or max(abs(x - y) for x, y in zip(j, last_j)) > 0.0005:
                last_move_t = time.time()
            last_j = j
            if time.time() - last_move_t > stall_s:
                print("    [track] 臂已%.1fs未动且未到终点 → 判停" % stall_s)
                return False, rec
        time.sleep(0.04)
    return False, rec

